
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,name TEXT NOT NULL,choices TEXT NOT NULL DEFAULT '[]',test_only INTEGER NOT NULL DEFAULT 1 CHECK(test_only=1));
CREATE TABLE IF NOT EXISTS variants(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),size TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('ready','made_to_order')),price_fils INTEGER NOT NULL CHECK(price_fils>=200),lead_days INTEGER NOT NULL CHECK(lead_days>=0),UNIQUE(product_id,size,kind));
CREATE TABLE IF NOT EXISTS stock(variant_id TEXT PRIMARY KEY REFERENCES variants(id),quantity INTEGER NOT NULL CHECK(quantity>=0));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,request_key TEXT UNIQUE NOT NULL,request_hash TEXT NOT NULL,tracking_hash TEXT UNIQUE NOT NULL,customer_email TEXT NOT NULL,address TEXT NOT NULL,payment_method TEXT NOT NULL CHECK(payment_method IN ('ziina','bank')),payment_status TEXT NOT NULL CHECK(payment_status IN ('pending','awaiting_transfer','partially_paid','paid')),fulfilment_status TEXT NOT NULL CHECK(fulfilment_status IN ('new','preparing','production','ready','shipped','delivered','needs_action')),total_fils INTEGER NOT NULL CHECK(total_fils>=200),received_fils INTEGER NOT NULL DEFAULT 0,created_at BIGINT NOT NULL,ship_at BIGINT NOT NULL,reservation_expires BIGINT NOT NULL,stock_committed INTEGER NOT NULL DEFAULT 0,test_only INTEGER NOT NULL DEFAULT 1 CHECK(test_only=1));
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),variant_id TEXT NOT NULL REFERENCES variants(id),name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),price_fils INTEGER NOT NULL,kind TEXT NOT NULL,size_mode TEXT NOT NULL CHECK(size_mode IN ('standard','custom')),size TEXT NOT NULL,options TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS measurements(order_id TEXT PRIMARY KEY REFERENCES orders(id),unit TEXT NOT NULL CHECK(unit IN ('cm','inch')),snapshot TEXT NOT NULL,definitions_version TEXT NOT NULL DEFAULT 'placeholder-v1',locked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reservations(order_id TEXT NOT NULL REFERENCES orders(id),variant_id TEXT NOT NULL REFERENCES variants(id),quantity INTEGER NOT NULL,expires_at BIGINT NOT NULL,PRIMARY KEY(order_id,variant_id));
CREATE TABLE IF NOT EXISTS payment_intents(operation_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),provider_id TEXT UNIQUE,status TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,redirect_url TEXT,created_at BIGINT NOT NULL,last_checked BIGINT NOT NULL DEFAULT 0,last_error TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_intent ON payment_intents(order_id) WHERE active=1;
CREATE TABLE IF NOT EXISTS webhook_events(hash TEXT PRIMARY KEY,intent_id TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS bank_transfers(reference TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),amount_fils INTEGER NOT NULL CHECK(amount_fils>0),created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications_outbox(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),event TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL,lease_until BIGINT NOT NULL DEFAULT 0,lease_token TEXT,last_error TEXT,UNIQUE(order_id,event));
CREATE TABLE IF NOT EXISTS audit_log(id TEXT PRIMARY KEY,order_id TEXT,actor TEXT NOT NULL,event TEXT NOT NULL,details TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_sessions(token_hash TEXT PRIMARY KEY,expires_at BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_state(id TEXT PRIMARY KEY,last_totp INTEGER NOT NULL DEFAULT -1,failures INTEGER NOT NULL DEFAULT 0,blocked_until BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,window_start BIGINT NOT NULL,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS catalogue_entries(product_id TEXT PRIMARY KEY REFERENCES products(id),payload TEXT NOT NULL,published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0,1)),revision INTEGER NOT NULL DEFAULT 1,updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS catalogue_images(id TEXT PRIMARY KEY,mime TEXT NOT NULL,bytes BYTEA NOT NULL,created_at BIGINT NOT NULL);

CREATE TABLE IF NOT EXISTS admin_push_subscriptions(endpoint_hash TEXT PRIMARY KEY,subscription TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_push_deliveries(id TEXT PRIMARY KEY,endpoint_hash TEXT NOT NULL REFERENCES admin_push_subscriptions(endpoint_hash),status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL,lease_until BIGINT NOT NULL DEFAULT 0);

-- Public Aulla catalogue only; quantities and lead times are test placeholders.
